-- ============================================================
-- 12295 / 12676 / 12677: the talent
-- ============================================================
-- Effect 1 was SPELL_AURA_DUMMY, effects 2 and 3 were ADD_PCT_MODIFIER with
-- EffectMiscValue 2 (SPELLMOD_THREAT).  Effects 1 and 2 become proc triggers
-- and effect 3 is zeroed.
--
-- Every stale field is cleared with the aura change -- EffectMiscValue2 (was 2,
-- load-bearing for ADD_PCT_MODIFIER and meaningless for a proc trigger),
-- EffectSpellClassMaskB1 (was 0x2000000, Mortal Strike),
-- EffectSpellClassMaskA2 (was 0x200, Bloodthirst) and C2.  Left in place these
-- would silently constrain which spells the new effects respond to.
--
-- ProcFlags 60 = 0x3C = DONE_MELEE_AUTO_ATTACK (0x4)
--                     | DONE_SPELL_MELEE_DMG_CLASS (0x10)
--                     | TAKEN_MELEE_AUTO_ATTACK (0x8)
--                     | TAKEN_SPELL_MELEE_DMG_CLASS (0x20)
-- Both directions are needed: the parry half is a taken event, the crit half is
-- a done event.  Which effect responds to which is decided in C++ -- see below.

DELETE FROM `alonecraft_spell_dbc` WHERE `ID` IN (12295, 12676, 12677);
