-- ============================================================
-- spell_proc
-- ============================================================
-- HitMask 34 = PROC_EX_CRITICAL_HIT (2) | PROC_EX_PARRY (32).  Both outcomes
-- have to be admitted here because spell_proc is per-SPELL, not per-effect --
-- there is no way to say "effect 0 on parry, effect 1 on crit" in this table.
-- That is the entire reason this talent needs a script: without one, a parry
-- would grant both buffs and so would a crit.
--
-- AttributesMask 2 = PROC_ATTR_TRIGGERED_CAN_PROC, so a critical Riposte
-- counterattack still feeds the crit half.  Riposte is a triggered spell, and
-- Aura::GetProcEffectMask drops procs from triggered spells without this flag.
--
-- SpellFamilyName 0 is deliberate even though the talent is family 4.  The
-- family filter is applied to the *triggering* spell: on the taken side that is
-- the enemy's attack, which is not warrior-family, so a family of 4 here would
-- kill the parry half outright.
--
-- SpellPhaseMask 2 is mandatory rather than cosmetic here -- the done-side
-- flags are inside REQ_SPELL_PHASE_PROC_FLAG_MASK, so a zero phase mask would
-- silently drop the crit half.

DELETE FROM `spell_proc` WHERE `SpellId` = -12295;
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(-12295, 0, 0, 0, 0, 0, 0, 0, 2, 34, 2, 0, 0, 0, 0, 0);

